"""
自定义异常模块 - 定义系统级异常类

提供结构化的异常处理和错误信息。
"""

from typing import Any


class LessonPlanException(Exception):
    """教案生成系统基础异常类。"""

    def __init__(
        self,
        message: str,
        code: int = 500,
        details: dict[str, Any] | None = None,
    ) -> None:
        """
        初始化异常。

        Args:
            message: 错误消息
            code: 错误码
            details: 详细信息
        """
        super().__init__(message)
        self.message = message
        self.code = code
        self.details = details or {}

    def to_dict(self) -> dict[str, Any]:
        """转换为字典格式。"""
        return {
            "code": self.code,
            "message": self.message,
            "details": self.details,
        }


class ValidationError(LessonPlanException):
    """请求参数验证错误。"""

    def __init__(
        self,
        message: str,
        field: str | None = None,
        details: dict[str, Any] | None = None,
    ) -> None:
        details = details or {}
        if field:
            details["field"] = field
        super().__init__(message=message, code=400, details=details)


class ResourceNotFoundError(LessonPlanException):
    """资源不存在错误。"""

    def __init__(
        self,
        resource_type: str,
        resource_id: str,
        message: str | None = None,
    ) -> None:
        message = message or f"{resource_type} '{resource_id}' 不存在"
        super().__init__(
            message=message,
            code=404,
            details={
                "resource_type": resource_type,
                "resource_id": resource_id,
            },
        )


class LLMServiceError(LessonPlanException):
    """LLM服务调用错误。"""

    def __init__(
        self,
        message: str,
        original_error: Exception | None = None,
    ) -> None:
        details = {}
        if original_error:
            details["original_error"] = str(original_error)
        super().__init__(message=message, code=503, details=details)


class ContentExtractionError(LessonPlanException):
    """内容提取错误。"""

    def __init__(
        self,
        message: str,
        source: str | None = None,
    ) -> None:
        details = {}
        if source:
            details["source"] = source
        super().__init__(message=message, code=500, details=details)


class DocumentConversionError(LessonPlanException):
    """文档转换错误。"""

    def __init__(
        self,
        message: str,
        target_format: str | None = None,
        original_error: Exception | None = None,
    ) -> None:
        details = {}
        if target_format:
            details["target_format"] = target_format
        if original_error:
            details["original_error"] = str(original_error)
        super().__init__(message=message, code=500, details=details)


class QuestionGenerationError(LessonPlanException):
    """问题生成错误。"""

    def __init__(
        self,
        message: str,
        plan_tags: list[str] | None = None,
    ) -> None:
        details = {}
        if plan_tags:
            details["plan_tags"] = plan_tags
        super().__init__(message=message, code=500, details=details)


class LessonGenerationError(LessonPlanException):
    """教案生成错误。"""

    def __init__(
        self,
        message: str,
        stage: str | None = None,
    ) -> None:
        details = {}
        if stage:
            details["stage"] = stage
        super().__init__(message=message, code=500, details=details)


class PolishError(LessonPlanException):
    """润色处理错误。"""

    def __init__(
        self,
        message: str,
        polish_rule: str | None = None,
    ) -> None:
        details = {}
        if polish_rule:
            details["polish_rule"] = polish_rule
        super().__init__(message=message, code=500, details=details)

"""
教案生成API路由模块

定义教案生成系统的所有HTTP接口。
"""

import sys
import traceback
from typing import Annotated
from fastapi import APIRouter, HTTPException, Query
from fastapi.responses import StreamingResponse, FileResponse
from loguru import logger

from models.requests import (
    QuestionGenerationRequest,
    LessonGenerationRequest,
    PolishParagraphRequest,
    DocumentExportRequest,
)
from models.responses import (
    BaseResponse,
    QuestionGenerationData,
    LessonGenerationData,
    PolishParagraphData,
    DocumentExportData,
)
from services import (
    question_service,
    lesson_service,
    polish_service,
    document_service,
)
from exceptions import LessonPlanException


# 创建路由器
router = APIRouter(prefix="/api/v1/lesson-plan", tags=["教案生成"])


@router.post(
    "/questions/generate",
    response_model=BaseResponse[QuestionGenerationData],
    summary="生成问题",
    description="根据课程信息和章节内容生成引导性问题，用于收集教师教学偏好",
)
async def generate_questions(
    request: QuestionGenerationRequest,
) -> BaseResponse[QuestionGenerationData]:
    """
    生成引导性问题接口。

    Args:
        request: 问题生成请求

    Returns:
        问题生成结果
    """
    try:
        logger.info(
            f"收到问题生成请求 | "
            f"course={request.course_title} | "
            f"tags_count={len(request.plan_tags)}"
        )

        result = await question_service.generate_questions(request)

        return BaseResponse.success(data=result)

    except LessonPlanException as e:
        logger.warning(f"问题生成业务异常 | {e.to_dict()}")
        return BaseResponse.error(code=e.code, message=e.message)
    except Exception as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(
            traceback.format_exception(exc_type, exc_value, exc_traceback)
        )
        logger.error(f"问题生成系统异常 | error={error_message}")
        return BaseResponse.error(message="服务器内部错误，请稍后重试")


@router.post(
    "/lesson/generate",
    response_model=BaseResponse[LessonGenerationData],
    summary="生成教案",
    description="根据问答结果和课程信息生成完整教案，支持流式和非流式输出",
)
async def generate_lesson(
    request: LessonGenerationRequest,
):
    """
    生成教案接口。

    Args:
        request: 教案生成请求

    Returns:
        教案生成结果（流式或非流式）
    """
    try:
        logger.info(
            f"收到教案生成请求 | "
            f"course={request.course_title} | "
            f"stream={request.stream}"
        )

        if request.stream:
            # 流式响应
            return StreamingResponse(
                lesson_service.generate_lesson_stream(request),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                },
            )
        else:
            # 非流式响应
            result = await lesson_service.generate_lesson(request)
            return BaseResponse.success(data=result)

    except LessonPlanException as e:
        logger.warning(f"教案生成业务异常 | {e.to_dict()}")
        if request.stream:
            raise HTTPException(status_code=e.code, detail=e.message)
        return BaseResponse.error(code=e.code, message=e.message)
    except Exception as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(
            traceback.format_exception(exc_type, exc_value, exc_traceback)
        )
        logger.error(f"教案生成系统异常 | error={error_message}")
        if request.stream:
            raise HTTPException(status_code=500, detail="服务器内部错误")
        return BaseResponse.error(message="服务器内部错误，请稍后重试")


@router.post(
    "/paragraph/polish",
    response_model=BaseResponse[PolishParagraphData],
    summary="段落润色",
    description="对教案中的特定段落进行润色优化，支持流式和非流式输出",
)
async def polish_paragraph(
    request: PolishParagraphRequest,
):
    """
    段落润色接口。

    Args:
        request: 润色请求

    Returns:
        润色结果（流式或非流式）
    """
    try:
        logger.info(
            f"收到润色请求 | "
            f"course={request.course_title} | "
            f"rule={request.polish_rule} | "
            f"stream={request.stream}"
        )

        if request.stream:
            # 流式响应
            return StreamingResponse(
                polish_service.polish_paragraph_stream(request),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                },
            )
        else:
            # 非流式响应
            result = await polish_service.polish_paragraph(request)
            return BaseResponse.success(data=result)

    except LessonPlanException as e:
        logger.warning(f"润色处理业务异常 | {e.to_dict()}")
        if request.stream:
            raise HTTPException(status_code=e.code, detail=e.message)
        return BaseResponse.error(code=e.code, message=e.message)
    except Exception as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(
            traceback.format_exception(exc_type, exc_value, exc_traceback)
        )
        logger.error(f"润色处理系统异常 | error={error_message}")
        if request.stream:
            raise HTTPException(status_code=500, detail="服务器内部错误")
        return BaseResponse.error(message="服务器内部错误，请稍后重试")


@router.post(
    "/document/export",
    response_model=BaseResponse[DocumentExportData],
    summary="导出文档",
    description="将教案内容导出为指定格式的文档（Word/PDF）",
)
async def export_document(
    request: DocumentExportRequest,
) -> BaseResponse[DocumentExportData]:
    """
    文档导出接口。

    Args:
        request: 文档导出请求

    Returns:
        文档导出结果
    """
    try:
        logger.info(
            f"收到文档导出请求 | "
            f"title={request.course_title} | "
            f"format={request.export_format}"
        )

        result = await document_service.export_document(request)

        return BaseResponse.success(data=result)

    except LessonPlanException as e:
        logger.warning(f"文档导出业务异常 | {e.to_dict()}")
        return BaseResponse.error(code=e.code, message=e.message)
    except Exception as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(
            traceback.format_exception(exc_type, exc_value, exc_traceback)
        )
        logger.error(f"文档导出系统异常 | error={error_message}")
        return BaseResponse.error(message="服务器内部错误，请稍后重试")


@router.get(
    "/files/download/{file_id}",
    summary="下载文件",
    description="根据文件ID下载已生成的文档",
)
async def download_file(
    file_id: str,
    format: Annotated[
        str,
        Query(description="文件格式", pattern="^(docx|pdf)$"),
    ] = "docx",
):
    """
    文件下载接口。

    Args:
        file_id: 文件ID
        format: 文件格式

    Returns:
        文件响应
    """
    try:
        logger.info(f"收到文件下载请求 | file_id={file_id} | format={format}")

        file_path = document_service.get_file_download_path(file_id, format)

        if not file_path:
            raise HTTPException(
                status_code=404,
                detail=f"文件不存在或已过期: {file_id}",
            )

        # 确定MIME类型
        media_type_map = {
            "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "pdf": "application/pdf",
        }
        media_type = media_type_map.get(format, "application/octet-stream")

        return FileResponse(
            path=file_path,
            media_type=media_type,
            filename=file_path.split("/")[-1],
        )

    except HTTPException:
        raise
    except Exception as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(
            traceback.format_exception(exc_type, exc_value, exc_traceback)
        )
        logger.error(f"文件下载异常 | error={error_message}")
        raise HTTPException(status_code=500, detail="文件下载失败")

